-- Maintenance procedures for menus (TAS009) and submenus (TAS011).
USE [cxView];
GO

CREATE OR ALTER PROCEDURE dbo.SP_TAS009_CREAR_MENU @idmodulo varchar(36),@menu varchar(50),@descripcion varchar(50),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS009(IDMENU,IDMOD,NOMMENU,DESCMENU,ESTMENU,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,LTRIM(RTRIM(@idmodulo)),LTRIM(RTRIM(@menu)),NULLIF(LTRIM(RTRIM(@descripcion)),''),'A',1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME()); SELECT * FROM dbo.TAS009 WHERE IDMENU=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS009_ACTUALIZAR_MENU @idmenu varchar(36),@idmodulo varchar(36),@menu varchar(50),@descripcion varchar(50),@estado varchar(1),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS009 SET IDMOD=LTRIM(RTRIM(@idmodulo)),NOMMENU=LTRIM(RTRIM(@menu)),DESCMENU=NULLIF(LTRIM(RTRIM(@descripcion)),''),ESTMENU=UPPER(LTRIM(RTRIM(@estado))),CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDMENU=LTRIM(RTRIM(@idmenu)) AND SACRG=1; SELECT * FROM dbo.TAS009 WHERE IDMENU=LTRIM(RTRIM(@idmenu)) AND SACRG=1; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS009_DAR_BAJA_MENU @idmenu varchar(36),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS009 SET ESTMENU='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDMENU=LTRIM(RTRIM(@idmenu)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS009_CONSULTAR_MENUS @idmenu varchar(36),@idmodulo varchar(36),@menu varchar(50),@estado varchar(1)
AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS009 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@idmenu)),'') IS NULL OR IDMENU=LTRIM(RTRIM(@idmenu))) AND (NULLIF(LTRIM(RTRIM(@idmodulo)),'') IS NULL OR IDMOD=LTRIM(RTRIM(@idmodulo))) AND (NULLIF(LTRIM(RTRIM(@menu)),'') IS NULL OR NOMMENU LIKE '%'+LTRIM(RTRIM(@menu))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTMENU=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY NOMMENU; END;
GO

CREATE OR ALTER PROCEDURE dbo.SP_TAS011_CREAR_SUBMENU @idmenu varchar(36),@submenu varchar(50),@descripcion varchar(100),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS011(IDSUBMENU,IDMENU,NOMSUBMNU,DESCSUBMNU,ESTSUBMNU,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,LTRIM(RTRIM(@idmenu)),LTRIM(RTRIM(@submenu)),NULLIF(LTRIM(RTRIM(@descripcion)),''),'A',1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME()); SELECT * FROM dbo.TAS011 WHERE IDSUBMENU=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS011_ACTUALIZAR_SUBMENU @idsubmenu varchar(36),@idmenu varchar(36),@submenu varchar(50),@descripcion varchar(100),@estado varchar(1),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS011 SET IDMENU=LTRIM(RTRIM(@idmenu)),NOMSUBMNU=LTRIM(RTRIM(@submenu)),DESCSUBMNU=NULLIF(LTRIM(RTRIM(@descripcion)),''),ESTSUBMNU=UPPER(LTRIM(RTRIM(@estado))),CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDSUBMENU=LTRIM(RTRIM(@idsubmenu)) AND SACRG=1; SELECT * FROM dbo.TAS011 WHERE IDSUBMENU=LTRIM(RTRIM(@idsubmenu)) AND SACRG=1; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS011_DAR_BAJA_SUBMENU @idsubmenu varchar(36),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS011 SET ESTSUBMNU='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDSUBMENU=LTRIM(RTRIM(@idsubmenu)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS011_CONSULTAR_SUBMENUS @idsubmenu varchar(36),@idmenu varchar(36),@submenu varchar(50),@estado varchar(1)
AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS011 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@idsubmenu)),'') IS NULL OR IDSUBMENU=LTRIM(RTRIM(@idsubmenu))) AND (NULLIF(LTRIM(RTRIM(@idmenu)),'') IS NULL OR IDMENU=LTRIM(RTRIM(@idmenu))) AND (NULLIF(LTRIM(RTRIM(@submenu)),'') IS NULL OR NOMSUBMNU LIKE '%'+LTRIM(RTRIM(@submenu))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTSUBMNU=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY NOMSUBMNU; END;
GO
